"use client"

import { useState, useRef, useEffect } from "react"
import { Card, CardContent } from "@/components/ui/card"
import { Button } from "@/components/ui/button"
import { Play, Pause, SkipForward, Music, Lock } from "lucide-react"
import { fetchUserGifts, type Gift } from "@/lib/user-data"

const TRACKS = [
  { id: "default", title: "Cozy Fireplace", src: "/audio/fireplace.mp3", locked: false },
  { id: "silver", title: "Silent Night Lo-Fi", src: "/audio/silent-night.mp3", locked: true, giftId: "2" }, // Requires Silver Badge
  { id: "gold", title: "Jingle Bells Jazz", src: "/audio/jingle-bells.mp3", locked: true, giftId: "3" },   // Requires Gold Badge
]

export function MusicPlayer() {
  const [isPlaying, setIsPlaying] = useState(false)
  const [currentTrackIndex, setCurrentTrackIndex] = useState(0)
  const [unlockedTracks, setUnlockedTracks] = useState<typeof TRACKS>(TRACKS)
  const audioRef = useRef<HTMLAudioElement | null>(null)

  useEffect(() => {
    checkUnlocks()
  }, [])

  const checkUnlocks = async () => {
    const gifts = await fetchUserGifts()
    const unlockedIds = new Set(gifts.filter(g => g.unlocked).map(g => g.id))
    
    setUnlockedTracks(TRACKS.map(track => ({
      ...track,
      locked: track.locked && track.giftId ? !unlockedIds.has(track.giftId) : false
    })))
  }

  const togglePlay = () => {
    if (audioRef.current) {
      if (isPlaying) {
        audioRef.current.pause()
      } else {
        audioRef.current.play()
      }
      setIsPlaying(!isPlaying)
    }
  }

  const nextTrack = () => {
    let nextIndex = (currentTrackIndex + 1) % TRACKS.length
    // Skip locked tracks
    while (unlockedTracks[nextIndex].locked) {
      nextIndex = (nextIndex + 1) % TRACKS.length
      if (nextIndex === currentTrackIndex) break // All locked?
    }
    setCurrentTrackIndex(nextIndex)
    setIsPlaying(true)
  }

  const currentTrack = unlockedTracks[currentTrackIndex]

  return (
    <Card className="fixed bottom-4 right-4 w-80 bg-black/80 backdrop-blur-md border-green-500/30 text-white shadow-2xl z-50">
      <CardContent className="p-4 flex items-center gap-4">
        <div className="bg-green-900/50 p-3 rounded-lg animate-pulse-slow">
          <Music className="h-6 w-6 text-green-400" />
        </div>
        
        <div className="flex-1 min-w-0">
          <p className="font-bold text-sm truncate text-green-100">{currentTrack.title}</p>
          <p className="text-xs text-green-400/70">Holiday Radio 📻</p>
        </div>

        <div className="flex gap-2">
          <Button size="icon" variant="ghost" className="h-8 w-8 text-white hover:text-green-400" onClick={togglePlay}>
            {isPlaying ? <Pause className="h-4 w-4" /> : <Play className="h-4 w-4" />}
          </Button>
          <Button size="icon" variant="ghost" className="h-8 w-8 text-white hover:text-green-400" onClick={nextTrack}>
            <SkipForward className="h-4 w-4" />
          </Button>
        </div>

        <audio
          ref={audioRef}
          src={currentTrack.src}
          autoPlay={isPlaying}
          onEnded={nextTrack}
          loop={false}
        />
      </CardContent>
      
      {/* Playlist Preview (Hover to see) */}
      <div className="absolute bottom-full right-0 mb-2 w-full bg-black/90 rounded-lg p-2 hidden group-hover:block">
         {unlockedTracks.map((t, i) => (
            <div key={t.id} className={`flex justify-between text-xs p-2 ${i === currentTrackIndex ? 'text-green-400' : 'text-gray-400'}`}>
               <span>{t.title}</span>
               {t.locked && <Lock className="h-3 w-3" />}
            </div>
         ))}
      </div>
    </Card>
  )
}
